package ir.alirezaivaz.mygarage;
import android.accounts.Account;import android.accounts.AccountManager;import android.app.Activity;import android.app.AlertDialog;import android.content.Intent;import android.content.SharedPreferences;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.graphics.Color;import android.provider.OpenableColumns;import android.webkit.JavascriptInterface;import android.webkit.JsResult;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.webkit.WebResourceRequest;import android.view.Window;import android.view.WindowManager;import android.widget.FrameLayout;import androidx.core.view.ViewCompat;import androidx.core.view.WindowCompat;import androidx.core.view.WindowInsetsCompat;import org.json.JSONObject;import com.google.android.gms.auth.GoogleAuthUtil;import com.google.android.gms.auth.GoogleAuthException;import com.google.android.gms.auth.UserRecoverableAuthException;import java.net.HttpURLConnection;import java.net.URL;import java.net.URLEncoder;import java.io.IOException;import java.io.ByteArrayOutputStream;import java.io.InputStream;import java.io.OutputStream;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity{
private static final int REQUEST_EXPORT=4101,REQUEST_IMPORT=4102,REQUEST_GOOGLE_ACCOUNT=4105,REQUEST_GOOGLE_AUTH=4106,MAX_BACKUP_BYTES=10*1024*1024;private static final String PREFS="mygarage_drive",PREF_URI="backup_uri",PREF_NAME="backup_name",PREF_ACCOUNT="google_account",PREF_FILE_ID="drive_file_id",PREF_SYNC="last_sync",DRIVE_SCOPE="https://www.googleapis.com/auth/drive.file",DRIVE_FILE_NAME="MyGarage-Backup.json";private WebView web;private String pendingBackupJson,pendingDriveJson;private boolean pendingDriveRestore;
public final class BackBridge{@JavascriptInterface public void exit(){runOnUiThread(MainActivity.this::finish);}}
public final class BackupBridge{
@JavascriptInterface public void exportBackup(String json){if(!valid(json)){notifyJs("onBackupSaved(false)");return;}runOnUiThread(()->{pendingBackupJson=json;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"my-car-service-backup.json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_EXPORT);}catch(Exception e){pendingBackupJson=null;notifyJs("onBackupSaved(false)");}});}
@JavascriptInterface public void importBackup(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,REQUEST_IMPORT);}catch(Exception e){notifyJs("onBackupFailed("+JSONObject.quote("انتخاب فایل در دسترس نیست.")+")");}});}
@JavascriptInterface public void connectDrive(){runOnUiThread(()->{if(prefs().getString(PREF_ACCOUNT,null)==null)chooseGoogleAccount();else notifyJs("onDriveConnected(true,"+JSONObject.quote(prefs().getString(PREF_ACCOUNT,""))+",'')");});}
@JavascriptInterface public void syncDrive(String json){if(!valid(json)){notifyJs("onDriveSyncResult(false,'',"+JSONObject.quote("اطلاعات پشتیبان نامعتبر یا بزرگ‌تر از ۱۰ مگابایت است.")+")");return;}pendingDriveJson=json;runOnUiThread(()->{if(prefs().getString(PREF_ACCOUNT,null)==null)chooseGoogleAccount();else syncDriveOnline(json);});}
@JavascriptInterface public void restoreDrive(){pendingDriveRestore=true;runOnUiThread(()->{if(prefs().getString(PREF_ACCOUNT,null)==null)chooseGoogleAccount();else restoreDriveOnline();});}
@JavascriptInterface public void getDriveStatus(){String a=prefs().getString(PREF_ACCOUNT,null);notifyJs("onDriveStatus("+(a!=null)+","+JSONObject.quote(a==null?"":a)+","+JSONObject.quote(prefs().getString(PREF_SYNC,""))+")");}}

private void chooseGoogleAccount(){try{Intent i=AccountManager.newChooseAccountIntent(null,null,new String[]{"com.google"},false,null,null,null,null);startActivityForResult(i,REQUEST_GOOGLE_ACCOUNT);}catch(Exception e){notifyJs("onDriveConnected(false,'',"+JSONObject.quote("انتخاب حساب گوگل ممکن نشد.")+")");}}
private String driveToken()throws IOException,GoogleAuthException{String name=prefs().getString(PREF_ACCOUNT,null);if(name==null)throw new IOException("ابتدا حساب گوگل را متصل کن.");return GoogleAuthUtil.getToken(this,new Account(name,"com.google"),"oauth2:"+DRIVE_SCOPE);}
private String driveHttp(String method,String address,String token,String body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(25000);c.setReadTimeout(30000);if("PATCH".equals(method)){c.setRequestMethod("POST");c.setRequestProperty("X-HTTP-Method-Override","PATCH");}else c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));o.flush();}}int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){try(InputStream src=in){byte[] buf=new byte[8192];int n;while((n=src.read(buf))!=-1){out.write(buf,0,n);if(out.size()>MAX_BACKUP_BYTES+65536)throw new IOException("پاسخ Google Drive بیش از حد بزرگ است.");}}}String response=out.toString(StandardCharsets.UTF_8.name());c.disconnect();if(code<200||code>=300)throw new IOException("Google Drive ("+code+"): "+response);return response;}
private String findDriveFile(String token)throws Exception{String q=URLEncoder.encode("name='"+DRIVE_FILE_NAME+"' and trashed=false","UTF-8");String response=driveHttp("GET","https://www.googleapis.com/drive/v3/files?q="+q+"&spaces=drive&fields=files(id,name)&pageSize=10",token,null);org.json.JSONArray files=new JSONObject(response).optJSONArray("files");return files!=null&&files.length()>0?files.getJSONObject(0).optString("id",null):null;}
private String createDriveFile(String token)throws Exception{JSONObject meta=new JSONObject();meta.put("name",DRIVE_FILE_NAME);meta.put("mimeType","application/json");String response=driveHttp("POST","https://www.googleapis.com/drive/v3/files?fields=id,name",token,meta.toString());return new JSONObject(response).getString("id");}
private void syncDriveOnline(String json){pendingDriveJson=json;new Thread(()->{try{String token=driveToken(),id=prefs().getString(PREF_FILE_ID,null);if(id==null||id.isEmpty()){id=findDriveFile(token);if(id==null)id=createDriveFile(token);prefs().edit().putString(PREF_FILE_ID,id).apply();}driveHttp("PATCH","https://www.googleapis.com/upload/drive/v3/files/"+URLEncoder.encode(id,"UTF-8")+"?uploadType=media",token,json);String stamp=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.US).format(new java.util.Date());prefs().edit().putString(PREF_SYNC,stamp).apply();pendingDriveJson=null;runOnUiThread(()->notifyJs("onDriveSyncResult(true,"+JSONObject.quote(stamp)+",'')"));}catch(UserRecoverableAuthException e){runOnUiThread(()->{try{startActivityForResult(e.getIntent(),REQUEST_GOOGLE_AUTH);}catch(Exception x){notifyJs("onDriveSyncResult(false,'',"+JSONObject.quote("تأیید دسترسی گوگل انجام نشد.")+")");}});}catch(Exception e){String msg=e.getMessage()==null?"اتصال به Google Drive ناموفق بود.":e.getMessage();runOnUiThread(()->notifyJs("onDriveSyncResult(false,"+JSONObject.quote(prefs().getString(PREF_SYNC,""))+","+JSONObject.quote(msg)+")"));}}).start();}
private void restoreDriveOnline(){new Thread(()->{try{String token=driveToken(),id=prefs().getString(PREF_FILE_ID,null);if(id==null||id.isEmpty()){id=findDriveFile(token);if(id==null)throw new IOException("فایل پشتیبان در حساب Google Drive پیدا نشد.");prefs().edit().putString(PREF_FILE_ID,id).apply();}String content=driveHttp("GET","https://www.googleapis.com/drive/v3/files/"+URLEncoder.encode(id,"UTF-8")+"?alt=media",token,null);pendingDriveRestore=false;runOnUiThread(()->{notifyJs("onDriveStatus(true,"+JSONObject.quote(prefs().getString(PREF_ACCOUNT,""))+","+JSONObject.quote(prefs().getString(PREF_SYNC,""))+")");notifyJs("onDriveRestoreResult(true,'')");notifyJs("onBackupLoaded("+JSONObject.quote(content)+")");});}catch(UserRecoverableAuthException e){runOnUiThread(()->{try{startActivityForResult(e.getIntent(),REQUEST_GOOGLE_AUTH);}catch(Exception x){notifyJs("onDriveRestoreResult(false,"+JSONObject.quote("تأیید دسترسی گوگل انجام نشد.")+")");}});}catch(Exception e){String msg=e.getMessage()==null?"بازیابی از Google Drive ناموفق بود.":e.getMessage();runOnUiThread(()->notifyJs("onDriveRestoreResult(false,"+JSONObject.quote(msg)+")"));}}).start();}
private void continueDriveAfterAuth(){String json=pendingDriveJson;if(json!=null){syncDriveOnline(json);return;}if(pendingDriveRestore){restoreDriveOnline();return;}notifyJs("onDriveConnected(true,"+JSONObject.quote(prefs().getString(PREF_ACCOUNT,""))+",'')");}
private boolean valid(String s){return s!=null&&s.getBytes(StandardCharsets.UTF_8).length<=MAX_BACKUP_BYTES;}private SharedPreferences prefs(){return getSharedPreferences(PREFS,MODE_PRIVATE);}
private String name(Uri u){try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(n>=0)return c.getString(n);}}catch(Exception ignored){}return "MyGarage-Backup.json";}
private void keep(Uri u,Intent d,boolean write){try{int f=d.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(write)f|=Intent.FLAG_GRANT_WRITE_URI_PERMISSION;getContentResolver().takePersistableUriPermission(u,f);}catch(Exception ignored){}prefs().edit().putString(PREF_URI,u.toString()).putString(PREF_NAME,name(u)).apply();}
private void writeDrive(Uri u,String json){new Thread(()->{boolean ok=false;String error="",stamp=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.US).format(new java.util.Date());try(OutputStream o=getContentResolver().openOutputStream(u,"wt")){if(o==null)throw new IllegalStateException("فایل Drive قابل نوشتن نیست.");o.write(json.getBytes(StandardCharsets.UTF_8));o.flush();prefs().edit().putString(PREF_SYNC,stamp).apply();ok=true;}catch(Exception e){error=e.getMessage()==null?"ذخیره در Drive ناموفق بود.":e.getMessage();}final boolean success=ok;final String msg=error;runOnUiThread(()->notifyJs("onDriveSyncResult("+success+","+JSONObject.quote(success?stamp:prefs().getString(PREF_SYNC,""))+","+JSONObject.quote(msg)+")"));}).start();}
private void readDrive(Uri u){new Thread(()->{String json=null,error="",sync="";try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream b=new ByteArrayOutputStream()){if(in==null)throw new IllegalStateException("فایل Drive قابل خواندن نیست.");byte[] x=new byte[8192];int n,total=0;while((n=in.read(x))!=-1){total+=n;if(total>MAX_BACKUP_BYTES)throw new IllegalStateException("حجم فایل بیشتر از ۱۰ مگابایت است.");b.write(x,0,n);}json=b.toString(StandardCharsets.UTF_8.name());try{sync=new JSONObject(json).optString("exportedAt","");if(!sync.isEmpty())prefs().edit().putString(PREF_SYNC,sync).apply();}catch(Exception ignored){}}catch(Exception e){error=e.getMessage()==null?"خواندن از Drive ناموفق بود.":e.getMessage();}final String content=json,msg=error,stamp=sync;runOnUiThread(()->{if(content!=null){notifyJs("onDriveStatus(true,"+JSONObject.quote(prefs().getString(PREF_NAME,""))+","+JSONObject.quote(stamp.isEmpty()?prefs().getString(PREF_SYNC,""):stamp)+")");notifyJs("onDriveRestoreResult(true,'')");notifyJs("onBackupLoaded("+JSONObject.quote(content)+")");}else notifyJs("onDriveRestoreResult(false,"+JSONObject.quote(msg)+")");});}).start();}
@Override protected void onCreate(Bundle b){super.onCreate(b);Window w=getWindow();w.setStatusBarColor(Color.rgb(11,20,32));w.setNavigationBarColor(Color.rgb(11,20,32));w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);if(android.os.Build.VERSION.SDK_INT>=29){w.setNavigationBarContrastEnforced(false);w.setStatusBarContrastEnforced(false);}WindowCompat.setDecorFitsSystemWindows(w,false);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(11,20,32));web=new WebView(this);web.setBackgroundColor(Color.rgb(11,20,32));web.setOverScrollMode(WebView.OVER_SCROLL_NEVER);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(false);s.setAllowFileAccess(true);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setSupportZoom(false);s.setBuiltInZoomControls(false);s.setDisplayZoomControls(false);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(android.os.Build.VERSION.SDK_INT>=26)s.setSafeBrowsingEnabled(true);web.addJavascriptInterface(new BackBridge(),"AndroidBack");web.addJavascriptInterface(new BackupBridge(),"AndroidFiles");web.setWebChromeClient(new WebChromeClient(){
@Override public boolean onJsConfirm(WebView view,String url,String message,JsResult result){
new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("تأیید",(dialog,which)->result.confirm()).setNegativeButton("انصراف",(dialog,which)->result.cancel()).setOnCancelListener(dialog->result.cancel()).show();return true;
}
});web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});root.addView(web,new FrameLayout.LayoutParams(-1,-1));ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());web.setPadding(0,bars.top,0,bars.bottom);return insets;});setContentView(root);ViewCompat.requestApplyInsets(root);web.loadUrl("file:///android_asset/index.html");}
private void notifyJs(String js){runOnUiThread(()->{if(web!=null)web.evaluateJavascript(js,null);});}
@Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);
if(req==REQUEST_GOOGLE_ACCOUNT){if(res!=RESULT_OK||data==null){pendingDriveJson=null;pendingDriveRestore=false;notifyJs("onDriveConnected(false,'',"+JSONObject.quote("انتخاب حساب گوگل لغو شد.")+")");return;}String account=data.getStringExtra(AccountManager.KEY_ACCOUNT_NAME);if(account==null||account.isEmpty()){notifyJs("onDriveConnected(false,'',"+JSONObject.quote("حساب گوگل انتخاب نشد.")+")");return;}prefs().edit().putString(PREF_ACCOUNT,account).apply();continueDriveAfterAuth();return;}
if(req==REQUEST_GOOGLE_AUTH){if(res==RESULT_OK){continueDriveAfterAuth();}else{pendingDriveJson=null;pendingDriveRestore=false;notifyJs("onDriveConnected(false,'',"+JSONObject.quote("دسترسی Google Drive تأیید نشد.")+")");}return;}
if(res!=RESULT_OK||data==null||data.getData()==null){if(req==REQUEST_EXPORT){pendingBackupJson=null;notifyJs("onBackupSaved(false)");}return;}Uri u=data.getData();
if(req==REQUEST_EXPORT){String json=pendingBackupJson;pendingBackupJson=null;try(OutputStream o=getContentResolver().openOutputStream(u)){if(o==null||json==null)throw new IllegalStateException();o.write(json.getBytes(StandardCharsets.UTF_8));o.flush();notifyJs("onBackupSaved(true)");}catch(Exception e){notifyJs("onBackupSaved(false)");}}
else if(req==REQUEST_IMPORT){try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream b=new ByteArrayOutputStream()){if(in==null)throw new IllegalStateException("فایل خوانده نشد.");byte[] x=new byte[8192];int n,total=0;while((n=in.read(x))!=-1){total+=n;if(total>MAX_BACKUP_BYTES)throw new IllegalStateException("حجم فایل بیشتر از ۱۰ مگابایت است.");b.write(x,0,n);}notifyJs("onBackupLoaded("+JSONObject.quote(b.toString(StandardCharsets.UTF_8.name()))+")");}catch(Exception e){notifyJs("onBackupFailed("+JSONObject.quote(e.getMessage()==null?"خواندن فایل ناموفق بود.":e.getMessage())+")");}}}
@Override public void onBackPressed(){if(web==null){super.onBackPressed();return;}web.evaluateJavascript("if(document.querySelector('.modal-back')){closeModal();}else if(document.body.dataset.page!=='home'){showPage('home');}else{AndroidBack.exit();}",null);}
@Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("AndroidBack");web.removeJavascriptInterface("AndroidFiles");web.stopLoading();web.loadUrl("about:blank");web.destroy();web=null;}super.onDestroy();}
}